import pyomo.environ as pyo

DATA = {
    "positions": ["X", "Y", "Z"],
    "salary": {"X": 5000, "Y": 4000, "Z": 6000},
    "min_hire": {"X": 30, "Y": 20, "Z": 10},
    "total_hire_limit": 100,
}


def build_model(data=None):
    d = data or DATA
    positions = d["positions"]

    model = pyo.ConcreteModel()
    model.POSITIONS = pyo.Set(initialize=positions, ordered=True)

    def hire_bounds(m, p):
        return (d["min_hire"][p], d["total_hire_limit"])

    model.hire = pyo.Var(
        model.POSITIONS,
        domain=pyo.NonNegativeIntegers,
        bounds=hire_bounds,
    )

    def obj_rule(m):
        return sum(d["salary"][p] * m.hire[p] for p in m.POSITIONS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_limit_rule(m):
        return sum(m.hire[p] for p in m.POSITIONS) <= d["total_hire_limit"]

    model.total_limit = pyo.Constraint(rule=total_limit_rule)

    def min_hire_rule(m, p):
        return m.hire[p] >= d["min_hire"][p]

    model.min_hire = pyo.Constraint(model.POSITIONS, rule=min_hire_rule)

    return model


